    "ingestedAt": "12/11/2026 às 20:59",
    "imageUrl": "https://www.camara.leg.br/midias/image/2026/11/img20261111174620952-768x473.jpg",
    "imageCaption": "Cerimônia de entrega da Medalha Rei Pelé",
